import api from '@/api'
import { createRouter, createWebHistory } from 'vue-router'
import LoginPage from '../views/LoginPage.vue'
import RegisterPage from '../views/RegisterPage.vue'
import WelcomePage from '../views/WelcomePage.vue'

const routes = [
  {
    path: '/login',
    name: 'LoginPage',
    component: LoginPage,
    meta: { requiresAuth: false }
  },
  {
    path: '/register',
    name: 'RegisterPage',
    component: RegisterPage,
    meta: { requiresAuth: false }
  },
  {
    path: '/welcome',
    name: 'WelcomePage',
    component: WelcomePage,
    meta: { requiresAuth: true }
  },
  {
    path: '/confirm-email',
    name: 'ConfirmEmailPage',
    component: () => import('@/views/ConfirmEmailPage.vue') // Создайте этот компонент
  },
  {
  path: '/activate-account',
  name: 'ActivateAccountPage',
  component: () => import('../views/ActivateAccountPage.vue'),
  props: route => ({ token: route.query.token })
},
  {
    path: '/',
    redirect: '/login'
  }
]

const router = createRouter({
  history: createWebHistory(process.env.BASE_URL),
  routes
})

router.beforeEach(async (to, from, next) => {
  const token = localStorage.getItem('authToken')

  if (to.meta.requiresAuth && !token) {
    next('/')
  } else if ((to.name === 'LoginPage' || to.name === 'RegisterPage') && token) {
    try {
      // Удаляем неиспользуемую переменную response
      await api.testToken(token)
      next('/welcome')
    } catch {
      localStorage.removeItem('authToken')
      next()
    }
  } else {
    next()
  }
})

export default router
